#!/usr/bin/env python3
from pathlib import Path

ROOT = Path("AIAssistantApp/app/src/main/java/com/example/aiassistant")

files = {
    "ResearchEngine.kt": 'package com.example.aiassistant\n\nimport java.net.URI\nimport java.util.LinkedHashMap\nimport java.util.Locale\n\nclass ResearchEngine(private val web: WebFallbackEngine) {\n    data class Report(\n        val answer: String,\n        val evidence: List<WebEvidence>,\n        val queries: List<String>,\n        val engines: List<String>\n    )\n\n    fun research(query: String, deep: Boolean = true): Report {\n        val q = query.trim()\n        if (q.isBlank()) return Report("Întrebarea este goală.", emptyList(), emptyList(), emptyList())\n\n        val queries = buildQueries(q, deep)\n        val all = mutableListOf<WebEvidence>()\n        val engines = linkedSetOf<String>()\n\n        for (candidate in queries) {\n            val result = try { web.ask(candidate) } catch (_: Exception) { null } ?: continue\n            engines += result.enginesTried\n            all += result.evidence\n        }\n\n        val unique = LinkedHashMap<String, WebEvidence>()\n        all.forEach { item ->\n            val normalized = normalizeUrl(item.url)\n            if (normalized.isNotBlank() && !unique.containsKey(normalized)) {\n                unique[normalized] = item\n            }\n        }\n\n        val evidence = unique.values\n            .sortedWith(\n                compareByDescending<WebEvidence> { sourceQuality(it) }\n                    .thenByDescending { it.content.length }\n                    .thenBy { it.title.lowercase(Locale.ROOT) }\n            )\n            .take(if (deep) 20 else 12)\n\n        val reasoning = EvidenceReasoningEngine.analyze(q, evidence)\n        return Report(\n            buildAnswer(q, evidence, queries, engines.toList(), reasoning),\n            evidence,\n            queries,\n            engines.toList()\n        )\n    }\n\n    private fun buildQueries(q: String, deep: Boolean): List<String> {\n        val list = mutableListOf(q)\n        if (deep) {\n            list += "$q surse oficiale primare"\n            list += "$q date studii documente originale"\n            list += "$q analiză independentă surse multiple"\n            list += "$q contradicții dezacord verificare"\n        } else {\n            list += "$q surse oficiale"\n            list += "$q verificare"\n        }\n        return list.distinct()\n    }\n\n    private fun buildAnswer(\n        query: String,\n        evidence: List<WebEvidence>,\n        queries: List<String>,\n        engines: List<String>,\n        reasoning: EvidenceReasoningEngine.Analysis\n    ): String = buildString {\n        append("🔬 DEEP RESEARCH MODE\\n\\n")\n        append("Întrebare: ").append(query).append(\'\\n\')\n        append("Treceri de cercetare: ").append(queries.size).append(\'\\n\')\n        append("Motoare încercate: ").append(if (engines.isEmpty()) "—" else engines.joinToString(", ")).append(\'\\n\')\n        append("Surse unice analizate: ").append(evidence.size).append(\'\\n\')\n        append("Surse distincte: ").append(reasoning.distinctDomains).append(\'\\n\')\n        append("Acoperire de evidență: ").append(reasoning.coverage).append("%\\n")\n        append("Independență estimată: ").append(reasoning.independence).append("%\\n\\n")\n\n        if (evidence.isEmpty()) {\n            append("Nu am obținut surse publice utilizabile. Nu voi inventa un răspuns.\\n")\n            return@buildString\n        }\n\n        append("🧠 ANALIZĂ A EVIDENȚEI\\n")\n        append(reasoning.summary).append("\\n\\n")\n\n        if (reasoning.conflicts.isNotEmpty()) {\n            append("⚠️ POSIBILE CONTRADICȚII\\n")\n            reasoning.conflicts.take(5).forEach { append("• ").append(it).append(\'\\n\') }\n            append(\'\\n\')\n        }\n\n        append("📚 SURSE ANALIZATE\\n")\n        evidence.take(if (evidence.size > 8) 12 else evidence.size).forEachIndexed { index, item ->\n            append("[").append(index + 1).append("] ")\n            append(item.title).append(\'\\n\')\n            append(item.url).append(\'\\n\')\n            append(item.content.ifBlank { item.snippet }.take(1000)).append("\\n\\n")\n        }\n\n        append("📌 Metodă: sursele sunt deduplicate, grupate după domeniu și evaluate după "\n            + "acoperirea termenilor, independența domeniilor, semnale de conflict și disponibilitatea "\n            + "conținutului. Scorurile sunt euristice și nu reprezintă o dovadă matematică.")\n    }\n\n    private fun sourceQuality(item: WebEvidence): Int {\n        val u = item.url.lowercase(Locale.ROOT)\n        var score = 0\n        if (u.contains(".gov") || u.contains(".edu") || u.contains(".int")) score += 40\n        if (u.contains("who.int") || u.contains("nasa.gov") || u.contains("esa.int")) score += 15\n        if (item.content.length > 1000) score += 20\n        if (item.snippet.length > 120) score += 5\n        return score\n    }\n\n    private fun normalizeUrl(url: String): String = try {\n        val u = URI(url)\n        (u.host.orEmpty().lowercase(Locale.ROOT) + u.path.orEmpty().trimEnd(\'/\')).trim()\n    } catch (_: Exception) {\n        url.substringBefore("#").trimEnd(\'/\').lowercase(Locale.ROOT)\n    }\n}\n',
    "FactCheckEngine.kt": 'package com.example.aiassistant\n\nimport java.util.Locale\n\nobject FactCheckEngine {\n    data class Check(\n        val supported: Int,\n        val weak: Int,\n        val conflict: Int,\n        val unknown: Int,\n        val report: String\n    )\n\n    fun check(answer: String, evidence: List<WebEvidence>): Check {\n        val claims = splitClaims(answer)\n        if (claims.isEmpty()) {\n            return Check(0, 0, 0, 0, "Nu au fost detectate afirmații suficient de lungi pentru verificare.")\n        }\n\n        var supported = 0\n        var weak = 0\n        var conflict = 0\n        var unknown = 0\n        val details = StringBuilder()\n\n        claims.take(20).forEachIndexed { index, claim ->\n            val result = EvidenceReasoningEngine.checkClaim(claim, evidence)\n            when (result.label) {\n                "SUPPORTED" -> supported++\n                "WEAK" -> weak++\n                "CONFLICT" -> conflict++\n                else -> unknown++\n            }\n\n            details.append(index + 1)\n                .append(". ")\n                .append(result.icon)\n                .append(\' \')\n                .append(result.labelText)\n                .append(" — scor ")\n                .append(result.score)\n                .append("%")\n                .append(\'\\n\')\n                .append("   ")\n                .append(claim.take(320))\n                .append(\'\\n\')\n                .append("   Surse relevante: ")\n                .append(result.sourceCount)\n                .append(" | domenii: ")\n                .append(result.domainCount)\n                .append(" | ")\n                .append(result.explanation)\n                .append(\'\\n\')\n        }\n\n        val report = buildString {\n            append("🔎 ADVANCED FACT CHECK\\n\\n")\n            append("Afirmații analizate: ").append(claims.size).append(\'\\n\')\n            append("✅ Susținute: ").append(supported).append(\'\\n\')\n            append("🟡 Susținere limitată: ").append(weak).append(\'\\n\')\n            append("⚠️ Posibil conflict: ").append(conflict).append(\'\\n\')\n            append("❓ Necunoscut: ").append(unknown).append("\\n\\n")\n            append(details)\n            append("\\nMetodă: potrivire normalizată de concepte + scor de sursă + diversitate de domenii "\n                + "+ semnale de contradicție. Rezultatul este un filtru automat de evidență, nu o certificare umană.")\n        }\n\n        return Check(supported, weak, conflict, unknown, report)\n    }\n\n    private fun splitClaims(text: String): List<String> =\n        text.replace(Regex("(?m)^\\\\s*[-•]\\\\s*"), "")\n            .split(Regex("(?<=[.!?])\\\\s+|\\\\n+"))\n            .map { it.trim() }\n            .filter { it.length >= 45 }\n            .filterNot { it.startsWith("http://") || it.startsWith("https://") }\n            .filterNot { it.startsWith("🔎") || it.startsWith("📌") }\n            .distinct()\n            .take(20)\n\n    private val STOP = setOf(\n        "care","este","sunt","pentru","despre","acest","această","aceste","acestea",\n        "unei","unui","mai","foarte","poate","fost","din","în","și","sau","with","from",\n        "that","this","there","their","have","will","about","into","were","been","than",\n        "the","and","for","are","was","has","had"\n    )\n}\n',
    "EvidenceReasoningEngine.kt": 'package com.example.aiassistant\n\nimport java.net.URI\nimport java.util.Locale\nimport kotlin.math.roundToInt\n\nobject EvidenceReasoningEngine {\n    data class Analysis(\n        val coverage: Int,\n        val independence: Int,\n        val distinctDomains: Int,\n        val summary: String,\n        val conflicts: List<String>\n    )\n\n    data class ClaimResult(\n        val label: String,\n        val labelText: String,\n        val icon: String,\n        val score: Int,\n        val sourceCount: Int,\n        val domainCount: Int,\n        val explanation: String\n    )\n\n    fun analyze(query: String, evidence: List<WebEvidence>): Analysis {\n        if (evidence.isEmpty()) {\n            return Analysis(0, 0, 0, "Nu există evidență analizabilă.", emptyList())\n        }\n\n        val domains = evidence.mapNotNull { domain(it.url) }.distinct()\n        val queryTerms = terms(query)\n        val coverageValues = evidence.map { overlap(queryTerms, terms(it.content + " " + it.snippet + " " + it.title)) }\n        val coverage = (coverageValues.average().coerceIn(0.0, 1.0) * 100).roundToInt()\n        val independence = (domains.size.toDouble() / evidence.size.coerceAtLeast(1) * 100.0)\n            .coerceIn(0.0, 100.0).roundToInt()\n\n        val conflicts = findConflicts(evidence)\n\n        val summary = buildString {\n            append("Am analizat ")\n            append(evidence.size)\n            append(" surse din ")\n            append(domains.size)\n            append(" domenii. ")\n            if (domains.size >= 3) {\n                append("Există diversitate de domenii, ceea ce reduce dependența de o singură pagină sau copie.")\n            } else {\n                append("Diversitatea domeniilor este redusă; mai multe rezultate pot proveni din aceeași familie de surse.")\n            }\n            if (conflicts.isNotEmpty()) {\n                append(" Au fost detectate semnale textuale care merită verificate manual.")\n            }\n        }\n\n        return Analysis(coverage, independence, domains.size, summary, conflicts)\n    }\n\n    fun checkClaim(claim: String, evidence: List<WebEvidence>): ClaimResult {\n        val claimTerms = terms(claim)\n        if (claimTerms.isEmpty()) {\n            return ClaimResult("UNKNOWN", "NEVERIFICABIL", "❓", 0, 0, 0, "Nu au fost extrase concepte utile.")\n        }\n\n        data class Match(val source: WebEvidence, val overlap: Double)\n        val matches = evidence.mapNotNull { source ->\n            val sourceTerms = terms(source.title + " " + source.snippet + " " + source.content)\n            val value = overlap(claimTerms, sourceTerms)\n            if (value >= 0.22) Match(source, value) else null\n        }.sortedByDescending { it.overlap }\n\n        val domains = matches.mapNotNull { domain(it.source.url) }.distinct()\n        val strong = matches.count { it.overlap >= 0.45 }\n        val medium = matches.count { it.overlap >= 0.30 }\n\n        val contradiction = hasContradictionSignal(claim) ||\n            matches.any { hasContradictionSignal(it.source.content + " " + it.source.snippet) }\n\n        val score = (\n            strong * 24 +\n            medium * 10 +\n            domains.size * 10 +\n            (if (matches.any { it.source.content.length > 1000 }) 8 else 0)\n        ).coerceIn(0, 100)\n\n        return when {\n            contradiction && matches.isNotEmpty() -> ClaimResult(\n                "CONFLICT", "POSIBIL CONFLICT / CONTEXT", "⚠️", score,\n                matches.size, domains.size,\n                "Există potrivire cu surse, dar și un semnal de negație/contrast."\n            )\n            strong >= 2 && domains.size >= 2 -> ClaimResult(\n                "SUPPORTED", "SUSȚINUT MULTI-SURSĂ", "✅", score,\n                matches.size, domains.size,\n                "Potrivire puternică în mai multe surse și domenii."\n            )\n            matches.isNotEmpty() -> ClaimResult(\n                "WEAK", "SUSȚINERE LIMITATĂ", "🟡", score,\n                matches.size, domains.size,\n                "Există evidență relevantă, dar independența sau potrivirea nu este suficientă."\n            )\n            else -> ClaimResult(\n                "UNKNOWN", "NEVERIFICAT", "❓", 0,\n                0, 0,\n                "Nu a fost găsită suficientă evidență relevantă."\n            )\n        }\n    }\n\n    private fun terms(text: String): Set<String> =\n        Regex("[\\\\p{L}\\\\p{Nd}]{4,}")\n            .findAll(normalize(text))\n            .map { it.value }\n            .filterNot { it in STOP }\n            .toSet()\n\n    private fun normalize(text: String): String =\n        text.lowercase(Locale.ROOT)\n            .replace(\'ă\', \'a\').replace(\'â\', \'a\').replace(\'î\', \'i\')\n            .replace(\'ș\', \'s\').replace(\'ş\', \'s\')\n            .replace(\'ț\', \'t\').replace(\'ţ\', \'t\')\n\n    private fun overlap(a: Set<String>, b: Set<String>): Double {\n        if (a.isEmpty() || b.isEmpty()) return 0.0\n        return a.intersect(b).size.toDouble() / a.size.toDouble()\n    }\n\n    private fun domain(url: String): String? = try {\n        URI(url).host?.lowercase(Locale.ROOT)?.removePrefix("www.")\n    } catch (_: Exception) {\n        null\n    }\n\n    private fun findConflicts(evidence: List<WebEvidence>): List<String> {\n        val signals = evidence.filter {\n            hasContradictionSignal(it.content + " " + it.snippet)\n        }\n        return signals.take(6).map {\n            "${it.title}: conține un semnal de negație/contrast; verifică pasajul original."\n        }\n    }\n\n    private fun hasContradictionSignal(text: String): Boolean =\n        Regex(\n            "(?i)\\\\b(contradict|contradiction|disput|deny|denied|false|incorrect|debunk|however|but|although|nu este|nu a fost|nu există|fals|incorect|contrazice|contestat)\\\\b"\n        ).containsMatchIn(text)\n\n    private val STOP = setOf(\n        "care","este","sunt","pentru","despre","acest","aceasta","aceste","acestea",\n        "unei","unui","mai","foarte","poate","fost","din","intr","între","prin","după",\n        "the","and","for","with","from","that","this","there","their","have","will",\n        "about","into","were","been","than","also","over","under"\n    )\n}\n',
}

for name, content in files.items():
    path = ROOT / name
    path.write_text(content, encoding="utf-8")
    print("Updated:", path)

print("\nResearch Reasoning Upgrade applied.")
print("This upgrade keeps the existing MainActivity interfaces compatible.")
print("It adds multi-query deep research, source-domain diversity, claim/evidence scoring,")
print("contradiction signals and a claim-level evidence matrix.")
